when HTTP_REQUEST {

       # Check the requested HTTP path
       switch -glob [string tolower [HTTP::path]] {
              "/apm_uri1*" -
              "/apm_uri2*" -
              "/apm_uri3*" {
                     # Enable APM for these paths
                     ACCESS::enable
              }
              default {
                     # Disable APM for all other paths
                     ACCESS::disable
              }
       }
}
